7	import * as fs from 'node:fs';
8	import * as path from 'node:path';
9	import type { Config } from '../config/config.js';
10	import { bfsFileSearchSync } from './bfsFileSearch.js';
11	
12	type SuccessfulPathCorrection = {
13	  success: true;
14	  correctedPath: string;
15	};
16	
17	type FailedPathCorrection = {
18	  success: false;
19	  error: string;
20	};
21	
22	/**
23	 * Attempts to correct a relative or ambiguous file path to a single, absolute path
24	 * within the workspace.
25	 *
26	 * @param filePath The file path to correct.
27	 * @param config The application configuration.
28	 * @returns A `PathCorrectionResult` object with either a `correctedPath` or an `error`.
29	 */
30	export type PathCorrectionResult =
31	  | SuccessfulPathCorrection
32	  | FailedPathCorrection;
33	export function correctPath(
34	  filePath: string,
35	  config: Config,
36	): PathCorrectionResult {
37	  // Check for direct path relative to the primary target directory.
38	  const directPath = path.join(config.getTargetDir(), filePath);
39	  if (fs.existsSync(directPath)) {
40	    return { success: true, correctedPath: directPath };
41	  }
42	
43	  // If not found directly, search across all workspace directories for ambiguous matches.
44	  const workspaceContext = config.getWorkspaceContext();
45	  const searchPaths = workspaceContext.getDirectories();
46	  const basename = path.basename(filePath);
47	  const normalizedTarget = filePath.replace(/\\/g, '/');
48	
49	  // Normalize path for matching and check if it ends with the provided relative path
50	  const foundFiles = searchPaths
51	    .flatMap((searchPath) =>
52	      bfsFileSearchSync(searchPath, {
53	        fileName: basename,
54	        maxDirs: 50, // Capped to avoid deep hangs
55	        fileService: config.getFileService(),
56	        fileFilteringOptions: config.getFileFilteringOptions(),
57	      }),
58	    )
59	    .filter((f) => f.replace(/\\/g, '/').endsWith(normalizedTarget));
60	
61	  if (foundFiles.length === 0) {
62	    return {
63	      success: false,
64	      error: `File not found for '${filePath}' and path is not absolute.`,
65	    };
66	  }
67	
68	  if (foundFiles.length > 1) {
69	    return {
70	      success: false,
71	      error: `The file path '${filePath}' is ambiguous and matches multiple files. Please provide a more specific path. Matches: ${foundFiles.join(', ')}`,
72	    };
73	  }
74	
75	  return { success: true, correctedPath: foundFiles[0] };
76	}
