64	class ReadFileToolInvocation extends BaseToolInvocation<
65	  ReadFileToolParams,
66	  ToolResult
67	> {
68	  private readonly resolvedPath: string;
69	  constructor(
70	    private config: Config,
71	    params: ReadFileToolParams,
72	    messageBus: MessageBus,
73	    _toolName?: string,
74	    _toolDisplayName?: string,
75	  ) {
76	    super(params, messageBus, _toolName, _toolDisplayName);
77	    this.resolvedPath = path.resolve(
78	      this.config.getTargetDir(),
79	      this.params.file_path,
80	    );
81	  }
82	
83	  getDescription(): string {
84	    const relativePath = makeRelative(
85	      this.resolvedPath,
86	      this.config.getTargetDir(),
87	    );
88	    return shortenPath(relativePath);
89	  }
90	
91	  override toolLocations(): ToolLocation[] {
92	    return [
93	      {
94	        path: this.resolvedPath,
95	        line: this.params.start_line,
96	      },
97	    ];
98	  }
99	
100	  override getPolicyUpdateOptions(
101	    _outcome: ToolConfirmationOutcome,
102	  ): PolicyUpdateOptions | undefined {
103	    return {
104	      argsPattern: buildFilePathArgsPattern(this.params.file_path),
105	    };
106	  }
107	
108	  async execute(_options: ExecuteOptions): Promise<ToolResult> {
109	    const validationError = this.config.validatePathAccess(
110	      this.resolvedPath,
111	      'read',
112	    );
113	    if (validationError) {
114	      return {
115	        llmContent: validationError,
116	        returnDisplay: 'Path not in workspace.',
117	        error: {
118	          message: validationError,
119	          type: ToolErrorType.PATH_NOT_IN_WORKSPACE,
120	        },
121	      };
122	    }
123	
124	    const result = await processSingleFileContent(
125	      this.resolvedPath,
126	      this.config.getTargetDir(),
127	      this.config.getFileSystemService(),
128	      this.params.start_line,
129	      this.params.end_line,
130	    );
131	
132	    if (result.error) {
133	      return {
134	        llmContent: result.llmContent,
135	        returnDisplay: result.returnDisplay || 'Error reading file',
136	        error: {
137	          message: result.error,
138	          type: result.errorType,
139	        },
140	      };
141	    }
142	
143	    let llmContent: PartListUnion;
144	    if (result.isTruncated) {
145	      const [start, end] = result.linesShown!;
146	      const total = result.originalLineCount!;
147	
148	      llmContent = `
149	IMPORTANT: The file content has been truncated.
150	Status: Showing lines ${start}-${end} of ${total} total lines.
151	Action: To read more of the file, you can use the 'start_line' and 'end_line' parameters in a subsequent 'read_file' call. For example, to read the next section of the file, use start_line: ${end + 1}.
152	
153	--- FILE CONTENT (truncated) ---
154	${result.llmContent}`;
155	    } else {
156	      llmContent = result.llmContent || '';
157	    }
158	
159	    const lines =
160	      typeof result.llmContent === 'string'
161	        ? result.llmContent.split('\n').length
162	        : undefined;
163	    const mimetype = getSpecificMimeType(this.resolvedPath);
164	    const programming_language = getProgrammingLanguage({
165	      file_path: this.resolvedPath,
166	    });
167	    logFileOperation(
168	      this.config,
169	      new FileOperationEvent(
170	        READ_FILE_TOOL_NAME,
171	        FileOperation.READ,
172	        lines,
173	        mimetype,
174	        path.extname(this.resolvedPath),
175	        programming_language,
176	      ),
177	    );
178	
179	    // Discover JIT subdirectory context for the accessed file path
180	    const jitContext = await discoverJitContext(this.config, this.resolvedPath);
181	    if (jitContext) {
182	      if (typeof llmContent === 'string') {
183	        llmContent = appendJitContext(llmContent, jitContext);
184	      } else {
185	        llmContent = appendJitContextToParts(llmContent, jitContext);
186	      }
187	    }
188	
189	    const displayResultSummary = result.isTruncated
190	      ? `${result.linesShown![0]}-${result.linesShown![1]} of ${result.originalLineCount}`
191	      : lines !== undefined
192	        ? `${lines} lines`
193	        : undefined;
194	
195	    return {
196	      llmContent,
197	      display: {
198	        name: READ_FILE_DISPLAY_NAME,
199	        description: this.getDescription(),
200	        resultSummary: displayResultSummary,
201	        result: { type: 'text', text: result.returnDisplay || '' },
202	      },
203	      returnDisplay: result.returnDisplay || '',
204	    };
205	  }
206	}
